"""Strangler-fig decomposition of the fines module (lesson 17 lab code).

Branch by abstraction: callers depend on FinesPort, never on the monolith. A facade routes each call to the
legacy code, to the extracted service, or to both (parallel run: legacy answers, the service is compared).
cutover_decision() turns the measured mismatch rate into a go/no-go. Run the demo: python app.py
"""
import hashlib
import json
import time
import urllib.parse
import urllib.request
from typing import Protocol

import legacy_monolith  # the ONLY new-code import of the monolith (fitness: legacy_callers.json)

CUTOVER = {"min_comparisons": 1000, "max_mismatch_rate": 0.001, "max_candidate_errors": 0}


class FinesPort(Protocol):  # branch by abstraction: the seam every caller uses
    def fine(self, days_late: int, member_type: str) -> str: ...


class LegacyFines:
    def fine(self, days_late, member_type):
        return legacy_monolith.calculate_fine(days_late, member_type)


class ServiceFines:
    """Calls the extracted service: over HTTP (base_url) or in-process (fn) for fast tests."""

    def __init__(self, base_url=None, fn=None, timeout=2.0):
        self.base_url, self.fn, self.timeout = base_url, fn, timeout

    def fine(self, days_late, member_type):
        if self.fn:
            return self.fn(days_late, member_type)
        query = urllib.parse.urlencode({"days_late": days_late, "member_type": member_type})
        with urllib.request.urlopen(f"{self.base_url}/fines?{query}", timeout=self.timeout) as resp:
            return json.loads(resp.read().decode("utf-8"))["fine"]


class ParallelRun:
    """Run control (legacy) and candidate (service); ALWAYS return the control; record every difference."""

    def __init__(self, control, candidate, log_path=None):
        self.control, self.candidate, self.log_path = control, candidate, log_path
        self.stats = {"comparisons": 0, "mismatches": 0, "candidate_errors": 0}
        self.mismatches = []

    def fine(self, days_late, member_type):
        expected = self.control.fine(days_late, member_type)
        try:
            actual = self.candidate.fine(days_late, member_type)
        except Exception as exc:  # a broken candidate must never break the member's request
            self.stats["candidate_errors"] += 1
            self._record({"days_late": days_late, "member_type": member_type, "error": repr(exc)})
            return expected
        self.stats["comparisons"] += 1
        if actual != expected:
            self.stats["mismatches"] += 1
            self._record({"days_late": days_late, "member_type": member_type, "control": expected,
                          "candidate": actual})
        return expected  # users only ever see the legacy answer while we compare

    def _record(self, row):
        self.mismatches.append(row)
        if self.log_path:  # JSON lines: one mismatch per line, for diagnosis
            with open(self.log_path, "a", encoding="utf-8") as f:
                f.write(json.dumps(row, sort_keys=True) + "\n")

    def mismatch_rate(self):
        return self.stats["mismatches"] / self.stats["comparisons"] if self.stats["comparisons"] else 0.0


def bucket(member_id):
    """Stable 0-99 bucket per member: a canary member stays in the canary on every request."""
    return int(hashlib.sha256(member_id.encode("utf-8")).hexdigest(), 16) % 100


class Facade:
    """The strangler facade. mode: legacy | shadow (parallel run) | canary (pct % to service) | service."""

    def __init__(self, legacy, service, mode="legacy", canary_pct=0, log_path=None):
        self.legacy, self.service, self.mode, self.canary_pct = legacy, service, mode, canary_pct
        self.shadow = ParallelRun(legacy, service, log_path)
        self.routed = {"legacy": 0, "service": 0}

    def fine(self, member_id, days_late, member_type):
        if self.mode == "service" or (self.mode == "canary" and bucket(member_id) < self.canary_pct):
            self.routed["service"] += 1
            return self.service.fine(days_late, member_type)
        self.routed["legacy"] += 1
        if self.mode == "shadow":
            return self.shadow.fine(days_late, member_type)
        return self.legacy.fine(days_late, member_type)


def cutover_decision(stats, criteria=CUTOVER):
    """Cut-over criteria as code: enough evidence, mismatch rate under budget, no candidate errors."""
    rate = stats["mismatches"] / stats["comparisons"] if stats["comparisons"] else 1.0
    reasons = []
    if stats["comparisons"] < criteria["min_comparisons"]:
        reasons.append(f"only {stats['comparisons']} comparisons (< {criteria['min_comparisons']})")
    if rate > criteria["max_mismatch_rate"]:
        reasons.append(f"mismatch rate {rate:.2%} > {criteria['max_mismatch_rate']:.2%}")
    if stats["candidate_errors"] > criteria["max_candidate_errors"]:
        reasons.append(f"{stats['candidate_errors']} candidate errors")
    return {"ready": not reasons, "mismatch_rate": round(rate, 4), "reasons": reasons}


def replay(facade, requests):
    """Send seeded traffic through the facade; returns elapsed seconds (informational only)."""
    start = time.perf_counter()
    for r in requests:
        facade.fine(r["member_id"], r["days_late"], r["member_type"])
    return time.perf_counter() - start

"""Three multi-tenancy layouts for Library Loans on SQLite files, measured side by side (lesson 18 lab code).

shared-schema      one file, one loans table, a tenant_id column on every row (isolation = a WHERE clause)
schema-per-tenant  one file, one loans table per tenant (SQLite has no CREATE SCHEMA: table name = namespace)
db-per-tenant      one SQLite file per tenant (isolation = the connection)
TenantGuard checks at runtime that every statement on a tenant table names the CURRENT tenant id.
Run the comparison: python app.py
"""
import re
import sqlite3
from datetime import date, timedelta

import repository

COLUMNS = "id INTEGER PRIMARY KEY, tenant_id TEXT NOT NULL, member_id TEXT NOT NULL, book_id TEXT NOT NULL, due TEXT"


class Session:
    """What a request gets: a connection, the table to use and the tenant it acts for."""

    def __init__(self, conn, table, tenant):
        self.conn, self.table, self.tenant = conn, table, tenant


class SharedSchema:
    kind = "shared-schema"

    def __init__(self, folder):
        self.path = folder / "shared.sqlite"

    def session(self, tenant, timeout=5.0):
        conn = sqlite3.connect(self.path, isolation_level=None, timeout=timeout)
        conn.execute(f"CREATE TABLE IF NOT EXISTS loans ({COLUMNS})")
        conn.execute("CREATE INDEX IF NOT EXISTS loans_tenant ON loans (tenant_id, member_id)")  # tenant first
        return Session(conn, "loans", tenant)

    def files(self, tenants):
        return 1

    def tables(self, tenants):
        return [("main", "loans")]


class SchemaPerTenant(SharedSchema):
    kind = "schema-per-tenant"

    def session(self, tenant, timeout=5.0):
        conn = sqlite3.connect(self.path, isolation_level=None, timeout=timeout)
        conn.execute(f"CREATE TABLE IF NOT EXISTS loans__{tenant} ({COLUMNS})")
        return Session(conn, f"loans__{tenant}", tenant)

    def tables(self, tenants):
        return [("main", f"loans__{t}") for t in tenants]


class DbPerTenant:
    kind = "db-per-tenant"

    def __init__(self, folder):
        self.folder = folder / "tenants"
        self.folder.mkdir(exist_ok=True)

    def session(self, tenant, timeout=5.0):
        conn = sqlite3.connect(self.folder / f"{tenant}.sqlite", isolation_level=None, timeout=timeout)
        conn.execute(f"CREATE TABLE IF NOT EXISTS loans ({COLUMNS})")
        return Session(conn, "loans", tenant)

    def files(self, tenants):
        return len(tenants)

    def tables(self, tenants):
        return [(t, "loans") for t in tenants]


LAYOUTS = [SharedSchema, SchemaPerTenant, DbPerTenant]
TENANT_TABLE = re.compile(r"\b(FROM|UPDATE|INTO|JOIN)\s+(loans\w*)", re.I)


class TenantGuard:
    """Runtime tenant scoping: the trace callback sees each statement with its bound values (expanded SQL)."""

    def __init__(self, session):
        self.session, self.violations = session, []

    def __enter__(self):
        self.session.conn.set_trace_callback(self.check)
        return self

    def __exit__(self, *exc):
        self.session.conn.set_trace_callback(None)

    def check(self, sql):
        if not TENANT_TABLE.search(sql) or sql.lstrip().upper().startswith(("CREATE", "BEGIN", "COMMIT")):
            return
        if f"'{self.session.tenant}'" not in sql:  # every tenant-table statement must carry THIS tenant's id
            self.violations.append(sql)


def seed(layout, tenants, loans_per_tenant=40, today=date(2026, 10, 28)):
    for t_index, tenant in enumerate(tenants):
        s = layout.session(tenant)
        s.conn.execute("BEGIN")
        for i in range(loans_per_tenant):  # every 3rd loan is overdue: due 1-5 days before today
            due = today - timedelta(days=1 + i % 5) if i % 3 == 0 else today + timedelta(days=7 + i % 14)
            repository.borrow(s, f"{tenant}-m{i % 12}", f"b{t_index}-{i}", due.isoformat())
        s.conn.execute("COMMIT")
        s.conn.close()


def leak_check(layout, tenant, today="2026-10-28"):
    """Isolation: rows from OTHER tenants returned by the overdue report, plus the guard's verdict."""
    s = layout.session(tenant)
    with TenantGuard(s) as guard:
        rows = repository.overdue(s, today)
    s.conn.close()
    return {"rows": len(rows), "leaked": sum(r[1].split("-")[0] != tenant for r in rows),
            "guard_violations": len(guard.violations)}


def noisy_neighbour(layout, busy_tenant, victim, attempts=20):
    """Tenant A holds a write transaction (bulk import); tenant B tries to borrow with no lock wait."""
    a = layout.session(busy_tenant)
    a.conn.execute("BEGIN IMMEDIATE")  # SQLite: one writer per FILE
    for i in range(500):
        repository.borrow(a, f"{busy_tenant}-bulk", f"bulk-{i}", "2026-12-01")
    b, blocked = layout.session(victim, timeout=0), 0
    for i in range(attempts):
        try:
            repository.borrow(b, f"{victim}-m1", f"new-{i}", "2026-11-11")
        except sqlite3.OperationalError:  # "database is locked": the neighbour's import blocks us
            blocked += 1
    a.conn.execute("ROLLBACK")
    a.conn.close()
    b.conn.close()
    return {"attempts": attempts, "blocked": blocked}


def migrate(layout, tenants, ddl="ALTER TABLE {db}.{table} ADD COLUMN renewals INTEGER NOT NULL DEFAULT 0"):
    """Migration effort: DDL statements to run and files to touch for ONE schema change."""
    statements = 0
    for db, table in layout.tables(tenants):
        s = layout.session(db if db != "main" else tenants[0])
        s.conn.execute(ddl.format(db="main", table=table))
        s.conn.close()
        statements += 1
    return {"ddl_statements": statements, "files": layout.files(tenants)}

"""A tiny Rego-like policy engine plus a decision point with decision logs (lesson 19 lab code).

FOR LEARNING ONLY: it reads a small subset of Rego v1 (default, `name if {...}`, `name contains "msg" if {...}`,
==, !=, <, <=, >, >=, in, not, count(), input./data. paths, string/number/bool/array literals). The same
policy file runs on OPA in CI. Policy = data the service loads; the service code only asks "allowed?".
"""
import hashlib
import json
import operator
import re

RULE = re.compile(r'^(\w+)(?:\s+contains\s+("[^"]*"))?\s+if\s*\{(.*?)^\}', re.S | re.M)
DEFAULT = re.compile(r"^default\s+(\w+)\s*:=\s*(.+)$", re.M)
OPS = [" == ", " != ", " <= ", " >= ", " < ", " > ", " in "]
COMPARE = dict(zip(OPS, [operator.eq, operator.ne, operator.le, operator.ge, operator.lt, operator.gt,
                         lambda left, right: left in right]))
UNDEFINED = object()  # Rego: a missing path is undefined, and an undefined expression is false


class Policy:
    def __init__(self, text):
        self.text = text
        self.revision = hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]  # logged with every decision
        self.defaults = {name: json.loads(value) for name, value in DEFAULT.findall(text)}
        self.rules = []  # (rule id, name, message or None, [conditions])
        for m in RULE.finditer(text):
            name, message, body = m.groups()
            line = text[:m.start()].count("\n") + 1
            conditions = [c.strip() for c in body.replace(";", "\n").splitlines()
                          if c.strip() and not c.strip().startswith("#")]
            self.rules.append((f"{name}@{line}", name, json.loads(message) if message else None, conditions))

    def evaluate(self, inp, data=None):
        """Returns (value of every rule name, ids of the rule bodies that matched)."""
        doc, matched, cache = {"input": inp, "data": data or {}}, [], {}

        def rule_value(name):
            if name not in cache:
                cache[name] = UNDEFINED  # guards against recursion
                bodies = [r for r in self.rules if r[1] == name]
                if bodies and bodies[0][2] is not None:  # partial set rule: collect messages
                    hits = [r for r in bodies if all(cond(c) for c in r[3])]
                    matched.extend(r[0] for r in hits)
                    cache[name] = sorted({r[2] for r in hits})
                else:  # boolean rule: any body true (bodies are OR-ed), else the default
                    hit = next((r for r in bodies if all(cond(c) for c in r[3])), None)
                    if hit:
                        matched.append(hit[0])
                    cache[name] = True if hit else self.defaults.get(name, UNDEFINED)
            return cache[name]

        def term(t):
            t = t.strip()
            if t.startswith("count(") and t.endswith(")"):
                value = term(t[6:-1])
                return UNDEFINED if value is UNDEFINED else len(value)
            if t.startswith(("input.", "data.")):
                value = doc
                for part in t.split("."):
                    value = value.get(part, UNDEFINED) if isinstance(value, dict) else UNDEFINED
                return value
            if re.fullmatch(r"\w+", t) and t not in ("true", "false") and not t.isdigit():
                return rule_value(t)
            return json.loads(t)  # "text", 5, 2.5, true, false, ["a", "b"]

        def cond(c):
            if c.startswith("not "):
                return not cond(c[4:])
            op = next((o for o in OPS if o in c), None)
            if op is None:
                return term(c) is True
            left, right = (term(x) for x in c.split(op, 1))
            if UNDEFINED in (left, right):
                return False
            try:
                return COMPARE[op](left, right)
            except TypeError:  # comparing e.g. a string with a number: undefined in Rego, false here
                return False

        values = {name: rule_value(name) for name in {r[1] for r in self.rules} | set(self.defaults)}
        return values, matched


MASK = ["/input/subject/email"]  # like OPA's system.log.mask: never write these fields to the decision log


class DecisionPoint:
    """PDP: evaluate the policy, return allowed + reasons, append one JSON line per decision.
    log_path: a file (opened per decision) or a list that collects the lines for a batched write."""

    def __init__(self, policy, log_path=None, clock=lambda: "2026-10-28T12:00:00Z"):
        self.policy, self.log_path, self.clock, self.count = policy, log_path, clock, 0

    def decide(self, inp):
        values, matched = self.policy.evaluate(inp)
        self.count += 1
        decision = {"allowed": values.get("allowed") is True, "deny": values.get("deny") or [],
                    "matched": matched}
        if self.log_path is not None:
            masked = json.loads(json.dumps(inp))
            erased = [p for p in MASK if _erase(masked, p.split("/")[2:])]
            event = {"decision_id": f"{self.policy.revision}-{self.count:06d}", "timestamp": self.clock(),
                     "path": "loans/authz/allowed", "revision": self.policy.revision, "input": masked,
                     "result": decision["allowed"], "deny": decision["deny"], "matched": matched, "erased": erased}
            if isinstance(self.log_path, list):
                self.log_path.append(json.dumps(event, sort_keys=True))
            else:
                with open(self.log_path, "a", encoding="utf-8") as f:
                    f.write(json.dumps(event, sort_keys=True) + "\n")
        return decision


def _erase(obj, parts):
    for part in parts[:-1]:
        obj = obj.get(part) if isinstance(obj, dict) else None
    return isinstance(obj, dict) and obj.pop(parts[-1], None) is not None


def load_policy(path):
    with open(path, encoding="utf-8") as f:
        return Policy(f.read())

"""Expand/contract (parallel change) for splitting members.name into given_name + family_name (lesson 20 lab code).

expand   add the new columns (old code keeps working: it never names them)
backfill copy old -> new in small batches (short transactions; dual-writing code keeps new rows in sync)
contract drop the old column - only when NOTHING still reads or writes it (can_contract)
Weakness (the failureLab): can_contract() only checks the backfill, not which code versions still run.
"""
import sqlite3

USES_OLD_COLUMN = {1: True, 2: True, 3: False}  # app version -> reads/writes members.name ?


def connect():
    db = sqlite3.connect(":memory:", isolation_level=None)
    db.execute("CREATE TABLE members (id INTEGER PRIMARY KEY, name TEXT)")  # nullable: v3 stops writing it
    return db


def columns(db):
    return [row[1] for row in db.execute("PRAGMA table_info(members)")]


def expand(db):
    if "given_name" not in columns(db):  # idempotent: safe to re-run after a failed deploy
        db.execute("ALTER TABLE members ADD COLUMN given_name TEXT")
        db.execute("ALTER TABLE members ADD COLUMN family_name TEXT")


def split(name):
    given, _, family = name.partition(" ")
    return given, family


def backfill(db, batch=50):
    """Copy name -> given/family for rows not yet migrated, one short transaction per batch."""
    done = 0
    while True:
        rows = db.execute("SELECT id, name FROM members WHERE given_name IS NULL LIMIT ?", (batch,)).fetchall()
        if not rows:
            return done
        db.execute("BEGIN")
        for member_id, name in rows:
            db.execute("UPDATE members SET given_name = ?, family_name = ? WHERE id = ?", (*split(name), member_id))
        db.execute("COMMIT")  # short transactions: readers and writers are never blocked for long
        done += len(rows)


def missing_new_values(db):
    if "given_name" not in columns(db):
        return None
    return db.execute("SELECT COUNT(*) FROM members WHERE given_name IS NULL").fetchone()[0]


def can_contract(db, fleet_versions):
    """Is it safe to drop members.name? Returns (ok, reasons)."""
    reasons = []
    if missing_new_values(db) != 0:
        reasons.append(f"{missing_new_values(db)} rows not backfilled")
    return not reasons, reasons  # weakness: running v1/v2 instances still use members.name


def contract(db):
    if "name" in columns(db):
        db.execute("ALTER TABLE members DROP COLUMN name")  # rewrites the table: time grows with rows

"""Capacity and cost planning from the lesson 15 request log (lesson 21 lab code).

load model    route mix + service times measured in the L300 log, scaled by the stated growth (libraries, peak)
Little's law  L = lambda x W: requests in flight = arrival rate x time in the system
benchmark     a seeded queue simulation of ONE instance (c workers, measured service times): the highest
              arrival rate whose p99 stays inside the SLO is the instance's capacity
sizing        instances_needed(); cost per million requests from a stated (hypothetical) instance price
Weakness (the failureLab): instances_needed() sizes on the AVERAGE rate at 100 % utilization.
"""
import heapq
import math
import random
import statistics

SLO_P99_MS = 300  # lesson 15: 99 % of requests under 300 ms
WORKERS = 4  # concurrent requests one instance serves (threads/processes)
HEADROOM = 0.8  # plan to use at most 80 % of the benchmarked capacity at peak (spikes, GC, deploys)


def load_model(records, libraries=400, peak_factor=3.0, seconds=3 * 86400):
    """records: the L300 log (one library). Returns the demand for `libraries` libraries."""
    per_library = len(records) / seconds  # 25,920 requests in 3 days = 0.1 req/s
    avg = per_library * libraries
    requests = [(r["route"], r["ms"]) for r in records]  # at 0.1 req/s nothing queues: latency = service time
    mix = {route: round(sum(q == route for q, _ in requests) / len(requests), 3) for route in sorted(set(
        q for q, _ in requests))}
    return {"avg_rps": round(avg, 1), "peak_rps": round(avg * peak_factor, 1), "mix": mix,
            "requests": requests, "mean_service_ms": round(statistics.fmean(ms for _, ms in requests), 1)}


def littles_law(rate_per_s, time_in_system_ms):
    return rate_per_s * time_in_system_ms / 1000  # L = lambda x W


def simulate(rate, service_ms, workers=WORKERS, n=20000, seed=21):
    """FCFS queue with `workers` servers, Poisson arrivals: returns latency percentiles and utilization."""
    rng, t, free = random.Random(seed), 0.0, [0.0] * workers  # heap of the times each worker becomes free
    latencies, busy = [], 0.0
    for _ in range(n):
        t += rng.expovariate(rate)  # next arrival (seconds)
        s = rng.choice(service_ms) / 1000
        start = max(t, heapq.heappop(free))  # wait for the first free worker
        heapq.heappush(free, start + s)
        latencies.append((start + s - t) * 1000)
        busy += s
    latencies.sort()
    return {"rate": rate, "p50_ms": round(latencies[n // 2], 1), "p99_ms": round(latencies[int(n * 0.99)], 1),
            "utilization": round(busy / (t * workers), 2), "in_flight": round(sum(latencies) / 1000 / t, 2)}


def benchmark(model, workers=WORKERS, step=5, high=200):
    """Capacity of ONE instance: the highest arrival rate (multiple of `step`) whose simulated p99 meets the SLO.
    Binary search: p99 grows with the rate."""
    service, rows = [ms for _, ms in model["requests"]], {}
    low, high = 1, high // step  # in units of `step` req/s
    while low <= high:
        mid = (low + high) // 2
        rows[mid * step] = simulate(mid * step, service, workers)
        low, high = (mid + 1, high) if rows[mid * step]["p99_ms"] <= SLO_P99_MS else (low, mid - 1)
    return {"capacity_rps": high * step, "rows": [rows[k] for k in sorted(rows)]}


def instances_needed(model, capacity_rps):
    """How many instances to run. Base version: average rate, every worker 100 % busy (the failureLab)."""
    raw_capacity = WORKERS / (model["mean_service_ms"] / 1000)  # c / S: requests per second at 100 %
    return math.ceil(model["avg_rps"] / raw_capacity)


def cost_per_million(instances, avg_rps, price_per_hour=0.10):
    """Hypothetical price (stated assumption, not a vendor quote): USD per instance-hour."""
    return round(instances * price_per_hour / (avg_rps * 3600) * 1e6, 2)


def change(model, route, new_ms):
    """Option helper: give `route` a new service time new_ms(old_ms, rng); recompute the mean."""
    rng = random.Random(211)
    requests = [(q, new_ms(ms, rng) if q == route else ms) for q, ms in model["requests"]]
    return {**model, "requests": requests, "mean_service_ms": round(statistics.fmean(ms for _, ms in requests), 1)}


def with_sync_email(model, email_ms=150.0):
    """The new LoanCreated email sent INSIDE POST /loans (stated relay time 150 ms per email)."""
    return change(model, "POST /loans", lambda ms, rng: ms + email_ms)


def with_cache(model, hit_ratio, hit_ms=2.0):
    """Cache GET /books: a hit costs hit_ms instead of the measured service time."""
    return change(model, "GET /books", lambda ms, rng: hit_ms if rng.random() < hit_ratio else ms)


def lru_hit_ratio(size=500, books=5000, requests=20000, seed=212):
    """Measured, not assumed: a seeded Zipf-like book popularity through an LRU cache of `size` entries."""
    rng, cache, hits = random.Random(seed), {}, 0
    weights = [1 / (rank + 1) for rank in range(books)]
    for book in rng.choices(range(books), weights, k=requests):
        if book in cache:
            hits += 1
            cache[book] = cache.pop(book)  # move to the most-recent end
        else:
            cache[book] = True
            if len(cache) > size:
                cache.pop(next(iter(cache)))  # evict the least recently used
    return round(hits / requests, 3)
